exercise.solution:
function composeFile() {
  return {
    services: {
      db: {
        image: "postgres:16",
        environment: {
          POSTGRES_DB: "shop",
          POSTGRES_USER: "shop",
          POSTGRES_PASSWORD: "secret"
        },
        volumes: ["db-data:/var/lib/postgresql/data"],
        healthcheck: {
          test: ["CMD-SHELL", "pg_isready -U shop"],
          interval: "5s",
          retries: 5
        }
      },
      api: {
        build: "./backend",
        environment: {
          SPRING_DATASOURCE_URL: "jdbc:postgresql://db:5432/shop",
          SPRING_DATASOURCE_USERNAME: "shop",
          SPRING_DATASOURCE_PASSWORD: "secret"
        },
        depends_on: {
          db: {
            condition: "service_healthy"
          }
        },
        ports: ["8080:8080"]
      },
      web: {
        build: "./frontend",
        depends_on: {
          api: {
            condition: "service_started"
          }
        },
        ports: ["80:80"]
      }
    },
    volumes: {
      "db-data": {}
    }
  };
}

function startOrder(services) {
  const names = Object.keys(services);
  const nameSet = new Set(names);
  const dependencies = new Map();

  for (const name of names) {
    const dependsOn = services[name]?.depends_on;
    const deps = Array.isArray(dependsOn)
      ? [...dependsOn]
      : dependsOn && typeof dependsOn === "object"
        ? Object.keys(dependsOn)
        : [];

    for (const dependency of deps) {
      if (!nameSet.has(dependency)) {
        throw new Error(`unknown dependency: ${dependency}`);
      }
    }

    dependencies.set(name, new Set(deps));
  }

  const remaining = new Map();
  for (const [name, deps] of dependencies) {
    remaining.set(name, new Set(deps));
  }

  const result = [];

  while (remaining.size > 0) {
    const ready = [...remaining.keys()]
      .filter((name) => remaining.get(name).size === 0)
      .sort();

    if (ready.length === 0) {
      throw new Error("cycle detected in dependencies");
    }

    for (const name of ready) {
      result.push(name);
      remaining.delete(name);
    }

    for (const deps of remaining.values()) {
      for (const name of ready) {
        deps.delete(name);
      }
    }
  }

  return result;
}

tests.code:
const stack = composeFile();
const db = stack?.services?.db;
return db?.image === "postgres:16" &&
  db?.environment?.POSTGRES_DB === "shop" &&
  db?.environment?.POSTGRES_USER === "shop" &&
  db?.environment?.POSTGRES_PASSWORD === "secret";

const services = {
  web: { depends_on: ["api", "cache"] },
  api: { depends_on: ["db"] },
  cache: {},
  db: {}
};
return JSON.stringify(startOrder(services)) === JSON.stringify(["cache", "db", "api", "web"]);

const services = {
  zebra: {},
  alpha: {},
  middle: {}
};
return JSON.stringify(startOrder(services)) === JSON.stringify(["alpha", "middle", "zebra"]);

const services = {
  api: { depends_on: ["db"] },
  db: { depends_on: ["api"] }
};
try {
  startOrder(services);
  return false;
} catch (error) {
  return String(error?.message).toLowerCase().includes("cycle");
}

const services = {
  web: { depends_on: { api: { condition: "service_started" } } },
  api: {}
};
const before = JSON.stringify(services);
const result = startOrder(services);
const after = JSON.stringify(services);
if (JSON.stringify(result) !== JSON.stringify(["api", "web"]) || before !== after) return false;

const invalid = { api: { depends_on: ["missing"] } };
try {
  startOrder(invalid);
  return false;
} catch (error) {
  return String(error?.message).toLowerCase().includes("unknown");
}
